def keep_one_placement_per_agent(apps, schema_editor):
    """A space kept one placement per (agent, blok); it keeps one per agent now: the latest."""
    Placement = apps.get_model("facade", "Placement")
    seen: set[tuple[int, int]] = set()
    for placement in Placement.objects.order_by("space_id", "agent_id", "-updated_at", "-id"):
        key = (placement.space_id, placement.agent_id)
        if key in seen:
            placement.delete()
        else:
            seen.add(key)


def reference_spaces_by_name(apps, schema_editor):
    """An existing space is found again by its name: the first of each name in an organization."""
    Space = apps.get_model("facade", "Space")
    taken: set[tuple[int, str]] = set()
    for space in Space.objects.order_by("organization_id", "name", "id"):
        key = (space.organization_id, space.name)
        if key not in taken:
            taken.add(key)
            Space.objects.filter(pk=space.pk).update(reference=space.name)


def drop_overlay_bloks(apps, schema_editor):
    """OVERLAY is no blok context any more: an action's Space blok replaces its overlay. An app sends
    its action bloks on every registration, so they come back as what it declares now."""
